    const validFrames = [
      validateMessage({type: 'list_sessions'}),
      validateMessage({
        type: 'list_sessions',
        limit: 0,
        before: {sessionId: 's1', updatedAt: 1700000000000, extra: 'ignored'},
        userId: 'u2',
      }),
      validateMessage({
        type: 'list_sessions',
        limit: 10,
        before: {sessionId: 's2', updatedAt: '2026-01-01T00:00:00.000Z'},
      }),
    ];
    const rejectedPayloads = [
      {type: 'list_sessions', limit: 'ten'},
      {type: 'list_sessions', limit: -1},
      {type: 'list_sessions', limit: 1.5},
      {type: 'list_sessions', before: 'not-an-object'},
      {type: 'list_sessions', before: null},
      {type: 'list_sessions', before: []},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 42}},
      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: '', sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: Number.NaN, sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
    ];

    expect({
      validFrames,
      rejectedValidFlags: rejectedPayloads.map(payload => validateMessage(payload).valid),
    }).toEqual({
      validFrames: [
        {valid: true, data: {type: 'list_sessions'}},
        {valid: true, data: {type: 'list_sessions', limit: 0, before: {sessionId: 's1', updatedAt: 1700000000000}}},
        {
          valid: true,
          data: {type: 'list_sessions', limit: 10, before: {sessionId: 's2', updatedAt: '2026-01-01T00:00:00.000Z'}},
        },
      ],
      rejectedValidFlags: Array(rejectedPayloads.length).fill(false),
    });
  });
});

